package com.yskj.shopify.web.service;
import com.alibaba.fastjson.JSONObject;import com.yskj.core.annotation.HkInject;import com.yskj.core.annotation.HkInjectService;import com.yskj.dao.dto.org.LoginedUser;import com.yskj.shopify.contract.connection.ICustomStoreConnectionService;import org.springframework.stereotype.Service;import java.util.*;
@HkInject @Service public class CustomStoreConnectionClient {
 @HkInjectService(ServiceName="shopifymarketingmerchant",ServicePackage="com.yskj.shopify.online.CustomStoreConnectionServiceImpl") private ICustomStoreConnectionService remote;
 public CustomStoreConnectionClient(){} public CustomStoreConnectionClient(ICustomStoreConnectionService remote){this.remote=remote;}
 public static String shop(String input){if(input==null)throw new IllegalArgumentException("店铺无效");String value=input.trim().toLowerCase(Locale.ROOT);if(value.length()>253||!value.matches("[a-z0-9]+(?:[a-z0-9.-]*[a-z0-9])?\\.[a-z0-9-]+")||value.contains(".."))throw new IllegalArgumentException("店铺域名无效");return value;}
 JSONObject request(LoginedUser user,String shop,JSONObject payload){if(user==null||user.getId()==null||user.getId().isBlank())throw new IllegalArgumentException("需要登录");var principal=new JSONObject();principal.put("id",user.getId());principal.put("domainid",user.getDomainid());principal.put("applicationid",user.getApplicationid());principal.put("aclNameList",user.getAclNameList());var r=new JSONObject();r.put("schemaVersion",1);r.put("surface","MERCHANT");r.put("user",principal);r.put("shopDomain",shop(shop));if(payload!=null)r.put("payload",payload);return r;}
 public JSONObject status(LoginedUser user,String shop){var r=request(user,shop,null);try{return view(remote.getConnection(r),r.getString("shopDomain"));}catch(RuntimeException unavailable){return unavailable(r.getString("shopDomain"));}}
 public JSONObject save(LoginedUser user,String shop,String url,String source,String epoch,String token,long version){request(user,shop,null);throw new IllegalStateException("连接配置仅由平台管理端维护");}
 public JSONObject probe(LoginedUser user,String shop,long version){var p=new JSONObject();p.put("expectedVersion",version);var r=request(user,shop,p);return command(()->remote.testConnection(r),r.getString("shopDomain"),false,version);}
 JSONObject command(java.util.function.Supplier<JSONObject> call,String shop,boolean saving,long expected){try{var raw=call.get();if(raw==null||raw.containsKey("errorCode")||Boolean.FALSE.equals(raw.get("success")))throw new IllegalStateException();var result=view(raw,shop);String state=result.getString("state");boolean valid=result.getBooleanValue("available")&&result.getBooleanValue("featureEnabled")&&result.getLongValue("version")==expected+(saving?1:0)&&(saving?result.getBooleanValue("configured")&&"PENDING_VERIFICATION".equals(state):Set.of("VERIFIED","FAILED").contains(state));if(!valid)throw new IllegalStateException();return result;}catch(RuntimeException unavailable){throw new IllegalStateException("连接操作未完成，请检查权限、配置版本或服务状态");}}
 public static JSONObject unavailable(String shop){var v=new JSONObject();v.put("available",false);v.put("featureEnabled",false);v.put("canConfigure",false);v.put("canTest",false);v.put("shopDomain",shop);v.put("state","UNAVAILABLE");v.put("signatureState","NOT_VERIFIED");v.put("syncEnabled",false);return v;}
 static JSONObject view(JSONObject raw,String shop){if(raw==null||raw.containsKey("errorCode")||!"1".equals(String.valueOf(raw.get("schemaVersion")))||!shop.equals(raw.getString("shopDomain"))||!"CUSTOM".equals(raw.getString("provider"))||!"AUW_V2".equals(raw.getString("connectorType"))||!Set.of("DISABLED","NOT_CONFIGURED","PENDING_VERIFICATION","VERIFIED","FAILED").contains(raw.getString("state")))return unavailable(shop);var v=new JSONObject();v.put("available",true);v.put("shopDomain",shop);for(String key:List.of("state","apiBaseUrl","lastCheckedAt","lastErrorCode")){Object value=raw.get(key);if(value instanceof String text&&text.length()<=2048)v.put(key,text);}for(String key:List.of("featureEnabled","configured"))v.put(key,Boolean.TRUE.equals(raw.get(key)));v.put("canConfigure",false);v.put("canTest",(raw.containsKey("canTest")?Boolean.TRUE.equals(raw.get("canTest")):Boolean.TRUE.equals(raw.get("canConfigure")))&&v.getBooleanValue("configured")&&v.getBooleanValue("featureEnabled"));Object version=raw.get("version");v.put("version",version instanceof Number?((Number)version).longValue():0);v.put("signatureState","NOT_VERIFIED");v.put("syncEnabled",false);v.put("environment","TEST");v.put("effectPolicy","SUPPRESS");return v;}

 public JSONObject sourceProfile(LoginedUser user,String shop){var r=request(user,shop,null);try{return profileView(remote.getSourceProfile(r),r.getString("shopDomain"));}catch(RuntimeException failure){return profileUnavailable(r.getString("shopDomain"));}}
 public JSONObject saveSourceProfile(LoginedUser user,String shop,String sourceType,String connectorKey,long expectedVersion){request(user,shop,null);throw new IllegalStateException("连接配置仅由平台管理端维护");}
 static boolean validPair(String source,String connector){return "SHOPIFY".equals(source)&&"SHOPIFY_NATIVE".equals(connector)||"SHOPLINE".equals(source)&&"SHOPLINE_PENDING".equals(connector)||"CUSTOM".equals(source)&&Set.of("NONE","AUW_V2").contains(connector==null?"":connector);}
 public static JSONObject profileUnavailable(String shop){var v=new JSONObject();v.put("available",false);v.put("shopDomain",shop);v.put("sourceType","UNKNOWN");v.put("sourceLabel","来源待确认");v.put("connectorKey","NONE");v.put("connectorLabel","连接信息暂不可用");v.put("connectorStatus","UNAVAILABLE");v.put("profileVersion",0);v.put("selectionAvailable",false);v.put("canSelect",false);return v;}
 static JSONObject profileView(JSONObject raw,String shop){
  if(raw==null||raw.containsKey("errorCode")||Boolean.FALSE.equals(raw.get("success"))||!Integer.valueOf(1).equals(raw.get("schemaVersion"))||!shop.equals(raw.getString("shopDomain"))||!validPair(raw.getString("sourceType"),raw.getString("connectorKey")))return profileUnavailable(shop);
  Object version=raw.get("profileVersion");if(!(version instanceof Number n)||n.longValue()<0||n.longValue()==Long.MAX_VALUE||n.doubleValue()!=n.longValue())return profileUnavailable(shop);
  String source=raw.getString("sourceType"),connector=raw.getString("connectorKey");String status="NONE".equals(connector)?"UNSELECTED":"SHOPLINE_PENDING".equals(connector)?"PLANNED":"READY";
  if(!status.equals(raw.getString("connectorStatus")))return profileUnavailable(shop);
  for(String field:List.of("selectionAvailable","canSelect","legacy"))if(!(raw.get(field) instanceof Boolean))return profileUnavailable(shop);
  var v=new JSONObject();v.put("available",true);v.put("shopDomain",shop);v.put("sourceType",source);v.put("connectorKey",connector);v.put("sourceLabel",Map.of("SHOPIFY","Shopify","SHOPLINE","Shopline","CUSTOM","自建站").get(source));v.put("connectorLabel",Map.of("SHOPIFY_NATIVE","Shopify 原生连接","SHOPLINE_PENDING","Shopline（待适配）","NONE","未选择连接器","AUW_V2","AUW v2").get(connector));v.put("connectorStatus",status);v.put("profileVersion",n.longValue());v.put("selectionAvailable",raw.getBooleanValue("selectionAvailable"));v.put("canSelect",false);v.put("legacy",raw.getBooleanValue("legacy"));v.put("bindingRequired",Boolean.TRUE.equals(raw.get("bindingRequired")));return v;
 }
}
